export function productionForecast(d,b,target,days=28){branch(d,b);date(target);days=number(days,7);if(!Number.isInteger(days)||days>180)throw Error('Histori harus 7–180 hari');const clock=Date.parse(target+'T12:00:00+07:00'),weekday=new Date(clock).getUTCDay(),start=new Date(clock-days*86400000).toISOString().slice(0,10),sampleDates=Array.from({length:days},(_,i)=>new Date(clock-(i+1)*86400000).toISOString().slice(0,10)).filter(t=>new Date(t+'T12:00:00+07:00').getUTCDay()===weekday),orders=d.orders.filter(o=>o.branch===b&&o.date>=start&&o.date<target&&o.status==='Selesai'&&o.paid&&sampleDates.includes(o.date)),menus=d.menus.filter(m=>m.available&&!m.combo).map(m=>{const sold=orders.reduce((s,o)=>s+o.lines.reduce((s,l)=>s+l.qty*(l.menuId===m.id?1:(l.comboChoices||[]).filter(c=>c.menuId===m.id).length),0),0),baseline=sampleDates.length?Math.ceil(sold/sampleDates.length):0,catering=(d.catering||[]).filter(c=>c.branch===b&&c.productionDate===target&&!['Dibatalkan','Selesai','Siap kirim','Diproduksi'].includes(c.status)).reduce((s,c)=>s+c.lines.reduce((s,l)=>s+l.qty*(l.menuId===m.id?1:(l.comboChoices||[]).filter(c=>c.menuId===m.id).length),0),0);return {menuId:m.id,name:m.name,baseline,catering,suggested:baseline+catering}});const needs=ingredientNeeds(d,{lines:menus.map(m=>({menuId:m.menuId,qty:m.suggested}))}),prep=(d.prepRecipes||[]).map(r=>{const i=ingredient(d,r.output),required=needs[i.id]||0,stock=usableStock(d,i.id,b),shortage=Math.max(0,required-stock);return {recipe:r.id,name:r.name,required,stock,unit:i.unit,outputQty:shortage,batches:shortage/r.outputQty}}).filter(r=>r.required>0);return {menus,prep,samples:sampleDates.length,days}}
export function requiresApproval(type,p){return ['business-discount','business-price','business-reopen-period'].includes(type)||type==='business-stock'&&['Kurangi','Opname'].includes(p.type)}
function mutateBatches(d,id,b,delta){let left=-delta;if(left<=0)return;for(const x of d.batches.filter(x=>x.ingredient===id&&x.branch===b&&x.remaining>0).sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999'))){const q=Math.min(left,x.remaining);x.remaining-=q;left-=q;if(left<=0)break}}
